// === TEXTO ===
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};

console.log('[TEXT] chatId:', data.chatId);
console.log('[TEXT] message:', data.body);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    text: data.body || '',
    inputType: 'text'
  }
};

// === ÁUDIO ===
// O áudio JÁ VEM em base64 no webhook, não precisa baixar!
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const media = data.media || {};

if (!media.data) {
  console.log('[AUDIO] Erro: media.data não encontrado');
  return {
    json: {
      skip: true,
      reason: 'media.data ausente'
    }
  };
}

// Converter base64 → Buffer → Binary
const audioBase64 = media.data;
const audioBuffer = Buffer.from(audioBase64, 'base64');

console.log('[AUDIO] Audio base64 length:', audioBase64.length);
console.log('[AUDIO] Audio buffer length:', audioBuffer.length);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    inputType: 'voice'
  },
  binary: {
    data: {
      data: audioBuffer.toString('base64'),
      mimeType: media.mimetype || 'audio/ogg',
      fileName: 'audio.ogg'
    }
  }
};

// === ÁUDIO TRANSCRITO ===
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const transcription = $json.text || '';

console.log('[AUDIO] Transcription:', transcription);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    text: `[🎤 ÁUDIO TRANSCRITO]\n${transcription}`,
    inputType: 'voice'
  }
};

// === IMAGEM ===
// A imagem JÁ VEM em base64 no webhook, não precisa baixar!
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const media = data.media || {};

if (!media.data) {
  console.log('[IMAGE] Erro: media.data não encontrado');
  return {
    json: {
      skip: true,
      reason: 'media.data ausente'
    }
  };
}

// Remover prefixo data:image se existir
let imageBase64 = media.data;
if (imageBase64.includes(',')) {
  imageBase64 = imageBase64.split(',')[1];
}

console.log('[IMAGE] Base64 length:', imageBase64.length);

// Criar estrutura binary para o Vision node
const imageBuffer = Buffer.from(imageBase64, 'base64');

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    caption: data.caption || 'Descreva esta imagem em detalhes',
    inputType: 'image'
  },
  binary: {
    data: {
      data: imageBuffer.toString('base64'),
      mimeType: media.mimetype || 'image/jpeg',
      fileName: 'image.jpg'
    }
  }
};

// === IMAGEM ANALISADA ===
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const visionResult = $json.content || '';

console.log('[IMAGE] Vision result:', visionResult);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    text: `[📷 IMAGEM]\nAnálise:\n${visionResult}`,
    inputType: 'image'
  }
};

// === DOCUMENTO ===
// O PDF JÁ VEM em base64 no webhook, não precisa baixar!
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const media = data.media || {};

if (!media.data) {
  console.log('[DOCUMENT] Erro: media.data não encontrado');
  return {
    json: {
      skip: true,
      reason: 'media.data ausente'
    }
  };
}

// ✅ FIX: Verificar mimetype em media.mimetype (não data.mimetype)
if (media.mimetype !== 'application/pdf') {
  console.log('[DOCUMENT] Não é PDF:', media.mimetype);
  return {
    json: {
      chatId: data.chatId,
      from: data.from,
      messageId: data.id,
      notPdf: true,
      mimetype: media.mimetype
    }
  };
}

// Converter base64 → Buffer → Binary
const pdfBase64 = media.data;
const pdfBuffer = Buffer.from(pdfBase64, 'base64');

console.log('[DOCUMENT] PDF base64 length:', pdfBase64.length);
console.log('[DOCUMENT] PDF buffer length:', pdfBuffer.length);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    filename: data.body || media.filename || 'document.pdf',
    inputType: 'document'
  },
  binary: {
    data: {
      data: pdfBuffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: data.body || media.filename || 'document.pdf'
    }
  }
};

// === PDF EXTRAÍDO ===
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const pdfText = $json.text || '';

console.log('[DOCUMENT] PDF text length:', pdfText.length);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    text: `[📄 DOCUMENTO PDF]\nConteúdo:\n${pdfText.substring(0, 3000)}...`,
    inputType: 'document'
  }
};

// === REJEITAR NÃO-PDF ===
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    text: `[❌ DOCUMENTO NÃO SUPORTADO]\nTipo: ${$json.mimetype || 'desconhecido'}\n\nPor favor, envie apenas arquivos PDF.`,
    inputType: 'document'
  }
};

// === LIMPAR RESPOSTA ===
const llmOutput = $input.first().json;
let text = llmOutput.text || llmOutput.output || '';

console.log('[CLEAN] ===== INICIO =====');
console.log('[CLEAN] Raw LLM output length:', text.length);
console.log('[CLEAN] First 200 chars:', text.substring(0, 200));

const originalLength = text.length;

// REGEX AGRESSIVO: Remover TUDO antes do último </think>
if (text.includes('<think>')) {
  console.log('[CLEAN] Found <think> tag, removing...');

  // Estratégia 1: Remover tudo até o ÚLTIMO </think>
  const lastCloseTag = text.lastIndexOf('</think>');
  if (lastCloseTag !== -1) {
    console.log('[CLEAN] Strategy 1: Removing everything before last </think>');
    text = text.substring(lastCloseTag + 8); // 8 = length of '</think>'
  }

  // Estratégia 2: Se ainda tem <think>, regex global
  text = text.replace(/<think>[\s\S]*?<\/think>/g, '');

  // Estratégia 3: Trim agressivo
  text = text.trim().replace(/^\n+/, '');

  const cleanedLength = text.length;
  console.log('[CLEAN] Removed', originalLength - cleanedLength, 'chars');
}

// Limitar tamanho (WhatsApp limit)
if (text.length > 4000) {
  console.log('[CLEAN] Truncating to 4000 chars');
  text = text.substring(0, 3997) + '...';
}

// Fallback se vazio
if (!text || text.trim().length === 0) {
  console.error('[CLEAN] ERROR: Text is empty after cleaning!');
  text = 'Desculpa, tive um problema ao processar. Pode repetir?';
}

console.log('[CLEAN] Final text length:', text.length);
console.log('[CLEAN] Final text:', text);
console.log('[CLEAN] ===== FIM =====');

// ✅ FIX: Buscar chatId e messageId do WEBHOOK, não do AI Agent
const webhookData = $('Webhook OpenWA').item.json.body;
const chatId = webhookData.data?.chatId;
const messageId = webhookData.data?.id;

return {
  json: {
    chatId: chatId,
    text: text,
    messageId: messageId
  }
};
